//! Independently loaded cache definitions; no synthetic positive metadata.
use gielinor_cache::{game::{Definitions,GameCache},symbols};
use gielinor_server::content::imcando_worn_swaps;
use std::{collections::BTreeMap,path::Path};
fn copy(d:&Definitions)->Definitions{Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:d.items.clone(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:d.stats.clone()}}
#[test]fn actual_worn_forms_and_thirty_eight_fail_closed_bindings(){let dir=std::env::var("PG_SYMBOLS").unwrap();let objects=symbols::load(&[Path::new(&dir)],"obj",None).unwrap();let path=std::env::var("PG_GAME_CACHE").unwrap();let mut cache=GameCache::open(Path::new(&path),0xff_ffff).unwrap();let items=cache.files(2,10,None).unwrap().unwrap();let mut defs=Definitions{inventories:BTreeMap::new(),locations:BTreeMap::new(),npcs:BTreeMap::new(),items:BTreeMap::new(),varbits:BTreeMap::new(),varps:BTreeMap::new(),stats:BTreeMap::new()};for id in[25644,29775]{defs.items.insert(id,gielinor_cache::definitions::ItemType::decode(&items[&id]).unwrap());}let rules=imcando_worn_swaps(&objects,&defs).unwrap();assert_eq!(rules.len(),2);for(input,output,slot)in[(25644,29775,3),(29775,25644,5)]{let d=&defs.items[&(input as u32)];assert!(d.members && !d.stackable);assert_eq!(d.wear[0],slot);assert_eq!(d.inventory_ops[2].as_deref(),Some("Swap"));let r=rules[&input];assert_eq!((r.output,r.from_slot,r.to_slot,r.button_operation),(output,slot as usize,if slot==3{5}else{3},2));assert_eq!(d.wear[1..],[-1,-1]);assert_eq!(d.params.get(&453),Some(&gielinor_cache::definitions::Param::String("Swap".into())));}
let mut refused=0;for(symbol,id)in[("imcando_hammer",25644),("imcando_hammer_offhand",29775)]{for case in 0..19{let mut d=copy(&defs);let mut o=objects.clone();match case{0=>{d.items.remove(&(id as u32));},1=>d.items.get_mut(&(id as u32)).unwrap().name="Wrong".into(),2=>d.items.get_mut(&(id as u32)).unwrap().members=false,3=>d.items.get_mut(&(id as u32)).unwrap().stackable=true,4=>d.items.get_mut(&(id as u32)).unwrap().dummy=1,5=>d.items.get_mut(&(id as u32)).unwrap().cert.template=799,6=>d.items.get_mut(&(id as u32)).unwrap().placeholder.template=14401,7=>d.items.get_mut(&(id as u32)).unwrap().transform.template=1,8=>d.items.get_mut(&(id as u32)).unwrap().inventory_ops[2]=None,9=>d.items.get_mut(&(id as u32)).unwrap().inventory_ops[2]=Some("Wield".into()),10=>d.items.get_mut(&(id as u32)).unwrap().wear[0]=0,11=>{o.remove(symbol);},12=>{o.insert(symbol.into(),id+100000);},13=>{d.items.get_mut(&(id as u32)).unwrap().wear[1]=3;},14=>{d.items.get_mut(&(id as u32)).unwrap().wear[2]=5;},15=>{d.items.get_mut(&(id as u32)).unwrap().params.remove(&453);},16=>{d.items.get_mut(&(id as u32)).unwrap().params.insert(453,gielinor_cache::definitions::Param::String("Wear".into()));},17=>{d.items.get_mut(&(id as u32)).unwrap().params.insert(453,gielinor_cache::definitions::Param::Integer(4));},_=>{d.items.get_mut(&(id as u32)).unwrap().wear[0]=-1;}}assert!(imcando_worn_swaps(&o,&d).is_err(),"{symbol} case{case}");refused+=1;}}assert_eq!(refused,38);println!("PG_IMCANDO_WORN_BINDINGS actual_items=2 exact_swap_index=2 component_button=2 secondarywear_none param453_Swap refusals=38");}
